package au.aumanet.app;

import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

/** Persist checked configuration, never active user consent. Uncertain storage remains fail closed. */
final class GatewayConfigStore {
    static final class Record {
        final long revision,previous,sourceRun;final String operation,process,digest;final GatewayBindingConfig config;final Set<String> approved;
        Record(long revision,long previous,String operation,String process,long sourceRun,String digest,GatewayBindingConfig config,Set<String> approved){this.revision=revision;this.previous=previous;this.operation=operation;this.process=process;this.sourceRun=sourceRun;this.digest=digest;this.config=config;this.approved=Collections.unmodifiableSet(new HashSet<>(approved));}
        void checked(GatewayOwnerAuthority.Scope scope){if(!config.group.equals(scope.group)||config.epoch!=scope.epoch||!config.owner.equals(scope.self)||!approved.equals(scope.approved))throw new SecurityException("Stored checked gateway configuration is stale for this membership");}
    }
    private final GatewaySequenceStore.Storage storage;private Record record;private boolean poisoned;
    GatewayConfigStore(GatewaySequenceStore.Storage storage)throws Exception{this.storage=storage;String saved=storage.read();if(saved==null)return;JSONObject value=GroupNameJson.object(saved,16384);GatewayBindingConfig.keys(value,"schema","revision","previousRevision","operationId","processId","sourceRun","digest","approvedPins","config");if(!"aumanet.gateway-checked-config.v1".equals(GroupNameMetadata.string(value,"schema")))throw new IllegalArgumentException("Unknown checked gateway configuration");long revision=GroupNameMetadata.number(value,"revision"),previous=GroupNameMetadata.number(value,"previousRevision"),run=GroupNameMetadata.number(value,"sourceRun");String operation=GroupNameMetadata.string(value,"operationId"),process=GroupNameMetadata.string(value,"processId"),digest=GroupNameMetadata.string(value,"digest");if(revision!=GroupNamePolicy.next(previous)||!GroupWire.id(operation)||!process.matches("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")||!digest.matches("[A-F0-9]{64}"))throw new IllegalArgumentException("Invalid checked gateway configuration metadata");JSONArray pins=value.getJSONArray("approvedPins");Set<String> approved=new HashSet<>();if(pins.length()<1||pins.length()>5)throw new IllegalArgumentException("Invalid saved gateway membership");for(int i=0;i<pins.length();i++){Object pin=pins.get(i);if(!(pin instanceof String)||!GroupWire.pin((String)pin)||!approved.add((String)pin))throw new IllegalArgumentException("Invalid saved gateway membership");}JSONObject cfg=value.getJSONObject("config");GatewayOwnerAuthority.Scope syntax=new GatewayOwnerAuthority.Scope(this,process,GroupNameMetadata.string(cfg,"ownerPin"),GroupNameMetadata.string(cfg,"groupId"),GroupNameMetadata.number(cfg,"epoch"),run,approved,null,null,0,false);GatewayBindingConfig config=GatewayBindingConfig.parse(cfg,syntax);if(!digest.equals(digest(config,approved)))throw new IllegalArgumentException("Checked gateway configuration digest differs");record=new Record(revision,previous,operation,process,run,digest,config,approved);}
    synchronized Record current(){if(poisoned)throw new IllegalStateException("Checked gateway configuration storage is uncertain");return record;}
    synchronized Record save(GatewayOwnerAuthority.Scope scope,JSONObject raw,long expected,String operation)throws Exception{
        if(poisoned)throw new IllegalStateException("Checked gateway configuration storage is uncertain");if(!GroupWire.id(operation))throw new IllegalArgumentException("Invalid gateway configuration operation");GatewayBindingConfig config=GatewayBindingConfig.parse(raw,scope);String digest=digest(config,scope.approved);
        if(record!=null&&record.operation.equals(operation)){if(record.previous!=expected||!record.process.equals(scope.process)||record.sourceRun!=scope.run||!record.digest.equals(digest))throw new SecurityException("Gateway configuration operation conflicts with another intent");record.checked(scope);return record;}
        if(record!=null&&record.config.routed()){if(!config.routed())throw new SecurityException("Explicit recovery is required to leave routed mode");for(GatewayBindingConfig.Node old:record.config.nodes){GatewayBindingConfig.Node found=null;for(GatewayBindingConfig.Node next:config.nodes)if(next.id.equals(old.id))found=next;if(found==null||found.lan.revision<old.lan.revision||!found.lan.network.equals(old.lan.network)||found.lan.revision==old.lan.revision&&!found.lan.bodyHex.equals(old.lan.bodyHex))throw new SecurityException("Routed allocation rollback/renumber rejected");}}
        long current=record==null?0:record.revision;if(current!=expected)throw new IllegalStateException("Checked gateway configuration changed; refresh before configuring");long revision=GroupNamePolicy.next(current);Record next=new Record(revision,current,operation,scope.process,scope.run,digest,config,scope.approved);JSONArray approved=new JSONArray();for(String pin:new TreeSet<>(scope.approved))approved.put(pin);String encoded=new JSONObject().put("schema","aumanet.gateway-checked-config.v1").put("revision",revision).put("previousRevision",current).put("operationId",operation).put("processId",scope.process).put("sourceRun",scope.run).put("digest",digest).put("approvedPins",approved).put("config",json(config)).toString();
        try{if(!storage.write(encoded))throw new IllegalStateException("Unconfirmed checked gateway configuration commit");}catch(Exception failure){poisoned=true;throw new IllegalStateException("Checked gateway configuration storage is uncertain; no field session started");}catch(Error interrupted){poisoned=true;throw interrupted;}record=next;return next;
    }
    static JSONObject json(GatewayBindingConfig config)throws Exception{JSONArray nodes=new JSONArray(),bindings=new JSONArray();for(GatewayBindingConfig.Node node:config.nodes){JSONObject value=new JSONObject().put("id",node.id).put("run",node.run);if(config.bootRecovery())value.put("publicKeyDerHex",node.publicKeyDerHex).put("publicKeySha256",node.publicKeySha256);if(config.routed())value.put("lanGrant",node.lan.json());nodes.put(value);}for(GatewayBindingConfig.Binding row:config.bindings)bindings.put(new JSONObject().put("phonePin",row.phone).put("attachmentNode",row.attachment).put("ipv4",row.address).put("mac",row.mac).put("generation",row.generation));JSONObject value=new JSONObject().put("schema",config.schema).put("groupId",config.group).put("epoch",config.epoch).put("ownerPin",config.owner).put("nodes",nodes).put("bindings",bindings);if(config.schema.equals("aumanet.gateway-config.v3")||config.routed())value.put("radioRelayNode",config.radioRelayNode());return value;}
    private static String digest(GatewayBindingConfig config,Set<String> approved)throws Exception{StringBuilder value=new StringBuilder(config.routed()?"AuMaNET checked gateway config v4\n":config.schema.equals("aumanet.gateway-config.v3")?"AuMaNET checked gateway config v3\n":config.bootRecovery()?"AuMaNET checked gateway config v2\n":"AuMaNET checked gateway config v1\n").append(config.group).append('\n').append(config.owner).append('\n').append(config.epoch).append('\n');if(config.schema.equals("aumanet.gateway-config.v3")||config.routed())value.append(config.radioRelayNode()).append('\n');for(String pin:new TreeSet<>(approved))value.append(pin).append('\n');List<GatewayBindingConfig.Node> nodes=new ArrayList<>(config.nodes);nodes.sort(Comparator.comparing(node->node.id));for(GatewayBindingConfig.Node node:nodes){value.append(node.id).append(':').append(node.run);if(config.bootRecovery())value.append(':').append(node.publicKeySha256).append(':').append(node.publicKeyDerHex);if(config.routed())value.append(':').append(node.lan.bodyHex).append(':').append(node.lan.signatureHex).append(':').append(node.lan.ownerDerHex).append(':').append(node.lan.ownerCertificateHex);value.append('\n');}List<GatewayBindingConfig.Binding> bindings=new ArrayList<>(config.bindings);bindings.sort(Comparator.comparing(row->row.phone));for(GatewayBindingConfig.Binding row:bindings)value.append(row.phone).append(':').append(row.attachment).append(':').append(row.address).append(':').append(row.mac).append(':').append(row.generation).append('\n');return GroupWire.hex(MessageDigest.getInstance("SHA-256").digest(value.toString().getBytes(StandardCharsets.US_ASCII)));}
}
